export type Item = { type: string; material?: string; enchantment?: number; cursed?: boolean };
export type Damage = { itemType: string; amount: number };
export type QuoteStep = { op: "quote"; items: Item[] };
export type ClaimStep = { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };
export type Scenario = { customer: { yearsWithMHPCO: number }; steps: (QuoteStep | ClaimStep)[] };
export type StepResult = { premium: number } | { payout: number; remainingCap: number };

const PROCESSING_FEE = 5;
const COMPONENT_BASE_PREMIUM = 25;
const ITEM_BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: COMPONENT_BASE_PREMIUM,
};
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;
const FIRST_INSURANCE_SURCHARGE = 0.1;

function buildingBlockDiscount(items: Item[]): number {
  const runeCount = items.filter((item) => item.type === "rune").length;
  return runeCount === BLOCK_SIZE ? BLOCK_SIZE * COMPONENT_BASE_PREMIUM - BLOCK_BASE_PREMIUM : 0;
}

function policyBasePremium(items: Item[]): number {
  return items.reduce((sum, item) => sum + ITEM_BASE_PREMIUMS[item.type], 0) - buildingBlockDiscount(items);
}

function quotePremium(items: Item[]): number {
  const base = policyBasePremium(items);
  return base + base * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE;
}

export function runScenario(scenario: Scenario): { results: StepResult[] } {
  return { results: scenario.steps.map((step) => ({ premium: quotePremium((step as QuoteStep).items) })) };
}
import { describe, expect, it } from "vitest";
import { type Item, runScenario } from "./claimOffice.js";

function premiumFor(items: Item[], yearsWithMHPCO = 0): number {
  const { results } = runScenario({ customer: { yearsWithMHPCO }, steps: [{ op: "quote", items }] });
  return (results[0] as { premium: number }).premium;
}

describe("quote", () => {
  it("empty item list -> premium 5 G (fee only; first insurance on 0 G base)", () => {
    expect(premiumFor([])).toBe(5);
  });
  it("newcomer with a plain sword -> 100 base + 10 first insurance + 5 fee = 115 G", () => {
    expect(premiumFor([{ type: "sword" }])).toBe(115);
  });
  it("newcomer with a plain amulet -> 60 + 6 + 5 = 71 G", () => {
    expect(premiumFor([{ type: "amulet" }])).toBe(71);
  });
  it("newcomer with a plain staff -> 80 + 8 + 5 = 93 G", () => {
    expect(premiumFor([{ type: "staff" }])).toBe(93);
  });
  it("newcomer with a plain potion -> 40 + 4 + 5 = 49 G", () => {
    expect(premiumFor([{ type: "potion" }])).toBe(49);
  });
  it("2 runes -> 50 G base -> 50 + 5 + 5 = 60 G", () => {
    expect(premiumFor([{ type: "rune" }, { type: "rune" }])).toBe(60);
  });
  it("3 runes -> block 60 G base -> 60 + 6 + 5 = 71 G", () => {
    expect(premiumFor([{ type: "rune" }, { type: "rune" }, { type: "rune" }])).toBe(71);
  });
  it("4 runes -> no block, 100 G base -> 100 + 10 + 5 = 115 G", () => {
    expect(premiumFor(Array.from({ length: 4 }, () => ({ type: "rune" })))).toBe(115);
  });
});

